/**
 * IIoT Model Schema Integration Tests
 *
 * Tests for Effect SQL Model schema validation and transforms against real PostgreSQL.
 * Verifies that Model.Generated, Model.GeneratedByApp, Model.FieldOption work correctly.
 *
 * Run with: RUN_INTEGRATION_TESTS=1 bun test src/lib/iiot/__tests__/models.integration.test.ts
 *
 * @module
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest'
import { Effect, Option, DateTime } from 'effect'
import {
  TestPgClient,
  RepositoriesIntegrationLayer,
  cleanTestAssets,
  cleanTestAlarms,
  cleanTestReadings,
  isDatabaseAvailable,
  setupTestHierarchy,
} from './integration/layer'
import {
  PlantRepo,
  LineRepo,
  MachineRepo,
  SensorRepo,
  AlarmRepo,
  SensorReadingRepo,
  AnalyticsRecordRepo,
} from '../repos'
import {
  testIds,
  testPlant1Insert,
  testPlant2Insert,
  testLine1Insert,
  testMachine1Insert,
  testMachine2Insert,
  testSensor1Insert,
  testAlarm1Insert,
  testAlarm2Insert,
  testSensorReading1Insert,
  testAnalyticsRecord1Insert,
  testAnalyticsRecord2Insert,
} from './__fixtures__/fixtures'

const RUN_INTEGRATION = process.env['RUN_INTEGRATION_TESTS'] === '1'

// =============================================================================
// Model.GeneratedByApp Tests
// =============================================================================

describe.skipIf(!RUN_INTEGRATION)('Model.GeneratedByApp Integration', () => {
  beforeAll(async () => {
    const available = await Effect.runPromise(
      isDatabaseAvailable.pipe(Effect.provide(TestPgClient))
    )
    if (!available) {
      throw new Error('Database not available')
    }
  })

  beforeEach(async () => {
    await Effect.runPromise(
      Effect.gen(function* () {
        yield* cleanTestAssets
        yield* setupTestHierarchy
      }).pipe(Effect.provide(TestPgClient))
    )
  })

  afterAll(async () => {
    await Effect.runPromise(
      cleanTestAssets.pipe(Effect.provide(TestPgClient))
    )
  })

  it('should require id in insert type (GeneratedByApp)', async () => {
    // PlantModel.id is Model.GeneratedByApp - must be provided by client
    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        return yield* plantRepo.insert(testPlant1Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    // The ID should exactly match what we provided
    expect(result.id).toBe(testIds.plant1)
  })

  it('should use client-provided ID for all GeneratedByApp fields', async () => {
    // Test across multiple models: Plant, Line, Machine, Sensor
    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        const lineRepo = yield* LineRepo
        const machineRepo = yield* MachineRepo
        const sensorRepo = yield* SensorRepo

        const plant = yield* plantRepo.insert(testPlant1Insert)
        const line = yield* lineRepo.insert(testLine1Insert)
        const machine = yield* machineRepo.insert(testMachine1Insert)
        const sensor = yield* sensorRepo.insert(testSensor1Insert)

        return { plant, line, machine, sensor }
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    expect(result.plant.id).toBe(testIds.plant1)
    expect(result.line.id).toBe(testIds.line1)
    expect(result.machine.id).toBe(testIds.machine1)
    expect(result.sensor.deviceId).toBe(testIds.device1)
  })
})

// =============================================================================
// Model.Generated Tests (Auto-generated by DB)
// =============================================================================

describe.skipIf(!RUN_INTEGRATION)('Model.Generated Integration', () => {
  beforeAll(async () => {
    const available = await Effect.runPromise(
      isDatabaseAvailable.pipe(Effect.provide(TestPgClient))
    )
    if (!available) {
      throw new Error('Database not available')
    }
  })

  beforeEach(async () => {
    await Effect.runPromise(
      Effect.gen(function* () {
        yield* cleanTestAlarms
        yield* cleanTestAssets
        yield* setupTestHierarchy
      }).pipe(Effect.provide(TestPgClient))
    )
    // Setup parent hierarchy for alarms
    await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        const lineRepo = yield* LineRepo
        const machineRepo = yield* MachineRepo
        const sensorRepo = yield* SensorRepo
        yield* plantRepo.insert(testPlant1Insert)
        yield* lineRepo.insert(testLine1Insert)
        yield* machineRepo.insert(testMachine1Insert)
        yield* sensorRepo.insert(testSensor1Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )
  })

  afterAll(async () => {
    await Effect.runPromise(
      cleanTestAlarms.pipe(Effect.provide(TestPgClient))
    )
    await Effect.runPromise(
      cleanTestAssets.pipe(Effect.provide(TestPgClient))
    )
  })

  it('should exclude id from insert type (Generated)', async () => {
    // AlarmModel.id is Model.Generated - should be auto-generated by DB
    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const alarmRepo = yield* AlarmRepo
        // testAlarm1Insert does NOT have id field - it's excluded from insert type
        return yield* alarmRepo.insert(testAlarm1Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    // The ID should be auto-generated and non-empty
    expect(result.id).toBeDefined()
    expect(typeof result.id).toBe('string')
    expect(result.id.length).toBeGreaterThan(0)
  })

  it('should generate unique IDs for each insert', async () => {
    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const alarmRepo = yield* AlarmRepo
        const alarm1 = yield* alarmRepo.insert(testAlarm1Insert)
        const alarm2 = yield* alarmRepo.insert(testAlarm2Insert)
        return { id1: alarm1.id, id2: alarm2.id }
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    expect(result.id1).not.toBe(result.id2)
  })
})

// =============================================================================
// Model.FieldOption Tests (NULL <-> Option)
// =============================================================================

describe.skipIf(!RUN_INTEGRATION)('Model.FieldOption Integration', () => {
  beforeAll(async () => {
    const available = await Effect.runPromise(
      isDatabaseAvailable.pipe(Effect.provide(TestPgClient))
    )
    if (!available) {
      throw new Error('Database not available')
    }
  })

  beforeEach(async () => {
    await Effect.runPromise(
      Effect.gen(function* () {
        yield* cleanTestAssets
        yield* setupTestHierarchy
      }).pipe(Effect.provide(TestPgClient))
    )
  })

  afterAll(async () => {
    await Effect.runPromise(
      cleanTestAssets.pipe(Effect.provide(TestPgClient))
    )
  })

  it('should store Option.some as non-NULL value', async () => {
    // PlantModel.siteId is Model.FieldOption (testing with siteId since location is now JSONB)
    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        return yield* plantRepo.insert(testPlant1Insert) // Has siteId: Some
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    expect(Option.isSome(result.siteId)).toBe(true)
  })

  it('should store Option.none as NULL value', async () => {
    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        return yield* plantRepo.insert(testPlant2Insert) // Has areaId: None
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    expect(Option.isNone(result.areaId)).toBe(true)
  })

  it('should retrieve NULL as Option.none', async () => {
    await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        yield* plantRepo.insert(testPlant2Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        return yield* plantRepo.findById(testIds.plant2)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    expect(Option.isSome(result)).toBe(true)
    const plant = Option.getOrThrow(result)
    expect(Option.isNone(plant.areaId)).toBe(true)
  })

  it('should handle optional modelNumber field correctly', async () => {
    // MachineModel.modelNumber is Model.FieldOption
    await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        const lineRepo = yield* LineRepo
        const machineRepo = yield* MachineRepo

        yield* plantRepo.insert(testPlant1Insert)
        yield* lineRepo.insert(testLine1Insert)
        yield* machineRepo.insert(testMachine1Insert) // Has modelNumber: Some
        yield* machineRepo.insert(testMachine2Insert) // Has modelNumber: None
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const machineRepo = yield* MachineRepo
        const machine1 = yield* machineRepo.findById(testIds.machine1)
        const machine2 = yield* machineRepo.findById(testIds.machine2)
        return { machine1, machine2 }
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const m1 = Option.getOrThrow(result.machine1)
    const m2 = Option.getOrThrow(result.machine2)

    expect(Option.isSome(m1.modelNumber)).toBe(true)
    expect(Option.getOrNull(m1.modelNumber)).toBe('Model X-100')
    expect(Option.isNone(m2.modelNumber)).toBe(true)
  })
})

// =============================================================================
// DateTime Transform Tests
// =============================================================================

describe.skipIf(!RUN_INTEGRATION)('DateTime Transform Integration', () => {
  beforeAll(async () => {
    const available = await Effect.runPromise(
      isDatabaseAvailable.pipe(Effect.provide(TestPgClient))
    )
    if (!available) {
      throw new Error('Database not available')
    }
  })

  beforeEach(async () => {
    await Effect.runPromise(
      Effect.gen(function* () {
        yield* cleanTestReadings
        yield* cleanTestAssets
        yield* setupTestHierarchy
      }).pipe(Effect.provide(TestPgClient))
    )
    // Setup parent hierarchy
    await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        const lineRepo = yield* LineRepo
        const machineRepo = yield* MachineRepo
        const sensorRepo = yield* SensorRepo
        yield* plantRepo.insert(testPlant1Insert)
        yield* lineRepo.insert(testLine1Insert)
        yield* machineRepo.insert(testMachine1Insert)
        yield* sensorRepo.insert(testSensor1Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )
  })

  afterAll(async () => {
    await Effect.runPromise(
      cleanTestReadings.pipe(Effect.provide(TestPgClient))
    )
    await Effect.runPromise(
      cleanTestAssets.pipe(Effect.provide(TestPgClient))
    )
  })

  it('should transform pg Date objects correctly (DateTimeInsertFromDate)', async () => {
    // PlantModel.createdAt uses Model.DateTimeInsertFromDate
    // Plant already inserted by beforeEach, query it to verify DateTime transform
    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        const plant = yield* plantRepo.findById(testIds.plant1)
        return Option.getOrThrow(plant)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    expect(DateTime.isDateTime(result.createdAt)).toBe(true)
    // updatedAt is Option<Date> - should be None for newly inserted record
    expect(Option.isNone(result.updatedAt)).toBe(true)
    // createdAt should be recent (within last minute)
    const now = new Date()
    const createdAtDate = DateTime.toDate(result.createdAt)
    expect(createdAtDate.getTime()).toBeLessThanOrEqual(now.getTime())
    expect(createdAtDate.getTime()).toBeGreaterThan(now.getTime() - 60000)
  })

  it('should store and retrieve sensor reading timestamps correctly', async () => {
    const testTime = testSensorReading1Insert.time

    await Effect.runPromise(
      Effect.gen(function* () {
        const readingRepo = yield* SensorReadingRepo
        yield* readingRepo.insert(testSensorReading1Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const readingRepo = yield* SensorReadingRepo
        return yield* readingRepo.findByKey(testTime, testIds.device1)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    expect(Option.isSome(result)).toBe(true)
    const reading = Option.getOrThrow(result)
    expect(reading.time).toBeInstanceOf(Date)
    // Timestamps should match (within second precision due to pg rounding)
    expect(Math.abs(reading.time.getTime() - testTime.getTime())).toBeLessThan(1000)
  })
})

// =============================================================================
// JSONB Storage Tests (JsonFromString)
// =============================================================================

describe.skipIf(!RUN_INTEGRATION)('JSONB Storage Integration', () => {
  beforeAll(async () => {
    const available = await Effect.runPromise(
      isDatabaseAvailable.pipe(Effect.provide(TestPgClient))
    )
    if (!available) {
      throw new Error('Database not available')
    }
  })

  beforeEach(async () => {
    await Effect.runPromise(
      Effect.gen(function* () {
        yield* cleanTestAlarms
        yield* cleanTestAssets
        yield* setupTestHierarchy
      }).pipe(Effect.provide(TestPgClient))
    )
    // Setup parent hierarchy
    await Effect.runPromise(
      Effect.gen(function* () {
        const plantRepo = yield* PlantRepo
        const lineRepo = yield* LineRepo
        const machineRepo = yield* MachineRepo
        const sensorRepo = yield* SensorRepo
        yield* plantRepo.insert(testPlant1Insert)
        yield* lineRepo.insert(testLine1Insert)
        yield* machineRepo.insert(testMachine1Insert)
        yield* sensorRepo.insert(testSensor1Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )
  })

  afterAll(async () => {
    await Effect.runPromise(
      cleanTestAlarms.pipe(Effect.provide(TestPgClient))
    )
    await Effect.runPromise(
      cleanTestAssets.pipe(Effect.provide(TestPgClient))
    )
  })

  it('should store and retrieve metadata as JSONB', async () => {
    // AlarmModel.metadata is Model.FieldOption(Model.JsonFromString(MetadataRecord))
    const insertedAlarm = await Effect.runPromise(
      Effect.gen(function* () {
        const alarmRepo = yield* AlarmRepo
        return yield* alarmRepo.insert(testAlarm1Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const alarmRepo = yield* AlarmRepo
        return yield* alarmRepo.findById(insertedAlarm.id)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    expect(Option.isSome(result)).toBe(true)
    const alarm = Option.getOrThrow(result)
    expect(Option.isSome(alarm.metadata)).toBe(true)
    const metadata = Option.getOrNull(alarm.metadata)
    expect(metadata).toEqual({ threshold: 80, actualValue: 85 })
  })

  it('should store complex nested JSONB', async () => {
    const complexMetadata = {
      threshold: 80,
      actualValue: 85,
      nested: {
        deep: {
          value: 'test',
        },
      },
      array: [1, 2, 3],
    }

    const insertedAlarm = await Effect.runPromise(
      Effect.gen(function* () {
        const alarmRepo = yield* AlarmRepo
        return yield* alarmRepo.insert({
          ...testAlarm1Insert,
          metadata: Option.some(complexMetadata),
        })
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const alarmRepo = yield* AlarmRepo
        return yield* alarmRepo.findById(insertedAlarm.id)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const alarm = Option.getOrThrow(result)
    const metadata = Option.getOrNull(alarm.metadata)
    expect(metadata).toEqual(complexMetadata)
  })

  it('should store null metadata as NULL (not empty object)', async () => {
    // testAlarm2Insert has metadata: None
    const insertedAlarm = await Effect.runPromise(
      Effect.gen(function* () {
        const alarmRepo = yield* AlarmRepo
        return yield* alarmRepo.insert(testAlarm2Insert)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const result = await Effect.runPromise(
      Effect.gen(function* () {
        const alarmRepo = yield* AlarmRepo
        return yield* alarmRepo.findById(insertedAlarm.id)
      }).pipe(Effect.provide(RepositoriesIntegrationLayer))
    )

    const alarm = Option.getOrThrow(result)
    expect(Option.isNone(alarm.metadata)).toBe(true)
  })
})

// =============================================================================
